10	package org.elasticsearch.action.admin.cluster.stats;
11	
12	import org.elasticsearch.action.admin.indices.stats.CommonStats;
13	import org.elasticsearch.index.cache.query.QueryCacheStats;
14	import org.elasticsearch.index.engine.SegmentsStats;
15	import org.elasticsearch.index.fielddata.FieldDataStats;
16	import org.elasticsearch.index.shard.DenseVectorStats;
17	import org.elasticsearch.index.shard.DocsStats;
18	import org.elasticsearch.index.shard.SparseVectorStats;
