29	public class ClusterStatsIndices implements ToXContentFragment {
30	    private final int indexCount;
31	    private final ShardStats shards;
32	    private final DocsStats docs;
33	    private final StoreStats store;
34	    private final SearchUsageStats searchUsageStats;
35	    private final FieldDataStats fieldData;
36	    private final QueryCacheStats queryCache;
37	    private final CompletionStats completion;
38	    private final SegmentsStats segments;
39	    private final AnalysisStats analysis;
40	    private final MappingStats mappings;
41	    private final VersionStats versions;
42	    private final DenseVectorStats denseVectorStats;
43	    private final SparseVectorStats sparseVectorStats;
44	
45	    public ClusterStatsIndices(
46	        List<ClusterStatsNodeResponse> nodeResponses,
47	        MappingStats mappingStats,
48	        AnalysisStats analysisStats,
49	        VersionStats versionStats
50	    ) {
51	        Map<String, ShardStats> countsPerIndex = new HashMap<>();
52	
53	        this.docs = new DocsStats();
54	        this.store = new StoreStats();
55	        this.searchUsageStats = new SearchUsageStats();
56	        this.fieldData = new FieldDataStats();
57	        this.queryCache = new QueryCacheStats();
58	        this.completion = new CompletionStats();
59	        this.segments = new SegmentsStats();
60	        this.denseVectorStats = new DenseVectorStats();
61	        this.sparseVectorStats = new SparseVectorStats();
62	
63	        for (ClusterStatsNodeResponse r : nodeResponses) {
64	            for (org.elasticsearch.action.admin.indices.stats.ShardStats shardStats : r.shardsStats()) {
65	                final String indexUuid = shardStats.getShardRouting().index().getUUID();
66	                ShardStats indexShardStats = countsPerIndex.get(indexUuid);
67	                if (indexShardStats == null) {
68	                    indexShardStats = new ShardStats();
69	                    countsPerIndex.put(indexUuid, indexShardStats);
70	                }
71	
72	                indexShardStats.total++;
73	
74	                CommonStats shardCommonStats = shardStats.getStats();
75	
76	                if (shardStats.getShardRouting().primary()) {
77	                    indexShardStats.primaries++;
78	                    docs.add(shardCommonStats.getDocs());
79	                    denseVectorStats.add(shardCommonStats.getDenseVectorStats());
80	                    sparseVectorStats.add(shardCommonStats.getSparseVectorStats());
81	                }
82	                store.add(shardCommonStats.getStore());
83	                fieldData.add(shardCommonStats.getFieldData());
84	                queryCache.add(shardCommonStats.getQueryCache());
85	                completion.add(shardCommonStats.getCompletion());
86	                segments.add(shardCommonStats.getSegments());
87	            }
88	
89	            searchUsageStats.add(r.searchUsageStats());
90	        }
91	
92	        shards = new ShardStats();
93	        indexCount = countsPerIndex.size();
94	        for (Map.Entry<String, ShardStats> indexCountsCursor : countsPerIndex.entrySet()) {
95	            shards.addIndexShardCount(indexCountsCursor.getValue());
96	        }
97	
98	        this.mappings = mappingStats;
99	        this.analysis = analysisStats;
100	        this.versions = versionStats;
101	    }
102	
103	    public int getIndexCount() {
104	        return indexCount;
105	    }
106	
107	    public ShardStats getShards() {
108	        return this.shards;
109	    }
110	
111	    public DocsStats getDocs() {
112	        return docs;
113	    }
114	
115	    public StoreStats getStore() {
116	        return store;
117	    }
118	
119	    public FieldDataStats getFieldData() {
120	        return fieldData;
121	    }
122	
123	    public QueryCacheStats getQueryCache() {
124	        return queryCache;
125	    }
126	
127	    public CompletionStats getCompletion() {
128	        return completion;
129	    }
130	
131	    public SegmentsStats getSegments() {
132	        return segments;
133	    }
134	
135	    public MappingStats getMappings() {
136	        return mappings;
137	    }
138	
139	    public AnalysisStats getAnalysis() {
140	        return analysis;
141	    }
142	
143	    public VersionStats getVersions() {
144	        return versions;
145	    }
146	
147	    public SearchUsageStats getSearchUsageStats() {
148	        return searchUsageStats;
149	    }
150	
151	    public DenseVectorStats getDenseVectorStats() {
152	        return denseVectorStats;
153	    }
154	
155	    public SparseVectorStats getSparseVectorStats() {
156	        return sparseVectorStats;
157	    }
158	
159	    static final class Fields {
160	        static final String COUNT = "count";
161	    }
162	
163	    @Override
164	    public XContentBuilder toXContent(XContentBuilder builder, Params params) throws IOException {
165	        builder.field(Fields.COUNT, indexCount);
166	        shards.toXContent(builder, params);
167	        docs.toXContent(builder, params);
168	        store.toXContent(builder, params);
169	        fieldData.toXContent(builder, params);
170	        queryCache.toXContent(builder, params);
171	        completion.toXContent(builder, params);
172	        segments.toXContent(builder, params);
173	        if (mappings != null) {
174	            mappings.toXContent(builder, params);
175	        }
176	        if (analysis != null) {
177	            analysis.toXContent(builder, params);
178	        }
179	        if (versions != null) {
180	            versions.toXContent(builder, params);
181	        }
182	        searchUsageStats.toXContent(builder, params);
183	        denseVectorStats.toXContent(builder, params);
184	        sparseVectorStats.toXContent(builder, params);
185	        return builder;
186	    }
187	
188	    public static class ShardStats implements ToXContentFragment {
189	
190	        int indices;
191	        int total;
192	        int primaries;
193	
194	        // min/max
195	        int minIndexShards = -1;
196	        int maxIndexShards = -1;
197	        int minIndexPrimaryShards = -1;
198	        int maxIndexPrimaryShards = -1;
199	        double minIndexReplication = -1;
200	        double totalIndexReplication = 0;
201	        double maxIndexReplication = -1;
202	
203	        public ShardStats() {}
204	
205	        /**
206	         * number of indices in the cluster
207	         */
208	        public int getIndices() {
209	            return this.indices;
210	        }
211	
212	        /**
213	         * total number of shards in the cluster
214	         */
215	        public int getTotal() {
216	            return this.total;
217	        }
218	
219	        /**
220	         * total number of primary shards in the cluster
221	         */
222	        public int getPrimaries() {
223	            return this.primaries;
224	        }
225	
226	        /**
227	         * returns how many *redundant* copies of the data the cluster holds - running with no replicas will return 0
228	         */
229	        public double getReplication() {
230	            if (primaries == 0) {
231	                return 0;
232	            }
233	            return (((double) (total - primaries)) / primaries);
234	        }
235	
236	        /**
237	         * the maximum number of shards (primary+replicas) an index has
238	         */
239	        public int getMaxIndexShards() {
240	            return this.maxIndexShards;
241	        }
242	
243	        /**
244	         * the minimum number of shards (primary+replicas) an index has
245	         */
246	        public int getMinIndexShards() {
247	            return this.minIndexShards;
248	        }
249	
250	        /**
251	         * average number of shards (primary+replicas) across the indices
252	         */
253	        public double getAvgIndexShards() {
254	            if (this.indices == 0) {
255	                return -1;
256	            }
257	            return ((double) this.total) / this.indices;
258	        }
259	
260	        /**
261	         * the maximum number of primary shards an index has
262	         */
263	        public int getMaxIndexPrimaryShards() {
264	            return this.maxIndexPrimaryShards;
265	        }
266	
267	        /**
268	         * the minimum number of primary shards an index has
269	         */
270	        public int getMinIndexPrimaryShards() {
271	            return this.minIndexPrimaryShards;
272	        }
273	
274	        /**
275	         * the average number primary shards across the indices
276	         */
277	        public double getAvgIndexPrimaryShards() {
278	            if (this.indices == 0) {
279	                return -1;
280	            }
281	            return ((double) this.primaries) / this.indices;
282	        }
283	
284	        /**
285	         * minimum replication factor across the indices. See {@link #getReplication}
286	         */
287	        public double getMinIndexReplication() {
288	            return this.minIndexReplication;
289	        }
290	
291	        /**
292	         * average replication factor across the indices. See {@link #getReplication}
293	         */
294	        public double getAvgIndexReplication() {
295	            if (indices == 0) {
296	                return -1;
297	            }
298	            return this.totalIndexReplication / this.indices;
299	        }
300	
301	        /**
302	         * maximum replication factor across the indices. See {@link #getReplication}
303	         */
304	        public double getMaxIndexReplication() {
305	            return this.maxIndexReplication;
306	        }
307	
308	        public void addIndexShardCount(ShardStats indexShardCount) {
309	            this.indices++;
310	            this.primaries += indexShardCount.primaries;
311	            this.total += indexShardCount.total;
312	            this.totalIndexReplication += indexShardCount.getReplication();
313	            if (this.indices == 1) {
314	                // first index, uninitialized.
315	                minIndexPrimaryShards = indexShardCount.primaries;
316	                maxIndexPrimaryShards = indexShardCount.primaries;
317	                minIndexShards = indexShardCount.total;
318	                maxIndexShards = indexShardCount.total;
319	                minIndexReplication = indexShardCount.getReplication();
320	                maxIndexReplication = minIndexReplication;
321	            } else {
322	                minIndexShards = Math.min(minIndexShards, indexShardCount.total);
323	                minIndexPrimaryShards = Math.min(minIndexPrimaryShards, indexShardCount.primaries);
324	                minIndexReplication = Math.min(minIndexReplication, indexShardCount.getReplication());
325	
326	                maxIndexShards = Math.max(maxIndexShards, indexShardCount.total);
327	                maxIndexPrimaryShards = Math.max(maxIndexPrimaryShards, indexShardCount.primaries);
328	                maxIndexReplication = Math.max(maxIndexReplication, indexShardCount.getReplication());
329	            }
330	        }
331	
332	        static final class Fields {
333	            static final String SHARDS = "shards";
334	            static final String TOTAL = "total";
335	            static final String PRIMARIES = "primaries";
336	            static final String REPLICATION = "replication";
337	            static final String MIN = "min";
338	            static final String MAX = "max";
339	            static final String AVG = "avg";
340	            static final String INDEX = "index";
341	        }
342	
343	        private static void addIntMinMax(String field, int min, int max, double avg, XContentBuilder builder) throws IOException {
344	            builder.startObject(field);
345	            builder.field(Fields.MIN, min);
346	            builder.field(Fields.MAX, max);
347	            builder.field(Fields.AVG, avg);
348	            builder.endObject();
349	        }
350	
351	        private static void addDoubleMinMax(String field, double min, double max, double avg, XContentBuilder builder) throws IOException {
352	            builder.startObject(field);
353	            builder.field(Fields.MIN, min);
354	            builder.field(Fields.MAX, max);
355	            builder.field(Fields.AVG, avg);
356	            builder.endObject();
357	        }
358	
359	        @Override
360	        public XContentBuilder toXContent(XContentBuilder builder, Params params) throws IOException {
361	            builder.startObject(Fields.SHARDS);
362	            if (indices > 0) {
363	
364	                builder.field(Fields.TOTAL, total);
365	                builder.field(Fields.PRIMARIES, primaries);
366	                builder.field(Fields.REPLICATION, getReplication());
367	
368	                builder.startObject(Fields.INDEX);
369	                addIntMinMax(Fields.SHARDS, minIndexShards, maxIndexShards, getAvgIndexShards(), builder);
370	                addIntMinMax(Fields.PRIMARIES, minIndexPrimaryShards, maxIndexPrimaryShards, getAvgIndexPrimaryShards(), builder);
371	                addDoubleMinMax(Fields.REPLICATION, minIndexReplication, maxIndexReplication, getAvgIndexReplication(), builder);
372	                builder.endObject();
373	            }
374	            builder.endObject();
375	            return builder;
376	        }
377	
378	        @Override
379	        public String toString() {
380	            return "total [" + total + "] primaries [" + primaries + "]";
381	        }
382	    }
383	}
