47	 */
48	public final class MappingStats implements ToXContentFragment, Writeable {
49	
50	    static final NodeFeature SOURCE_MODES_FEATURE = new NodeFeature("cluster.stats.source_modes");
51	
52	    private static final Pattern DOC_PATTERN = Pattern.compile("doc[\\[.]");
53	    private static final Pattern SOURCE_PATTERN = Pattern.compile("params\\._source");
54	
55	    /**
56	     * Create {@link MappingStats} from the given cluster state.
57	     */
58	    public static MappingStats of(Metadata metadata, Runnable ensureNotCancelled) {
59	        Map<String, FieldStats> fieldTypes = new HashMap<>();
60	        Set<String> concreteFieldNames = new HashSet<>();
61	        // Account different source modes based on index.mapping.source.mode setting:
62	        Map<String, Integer> sourceModeUsageCount = new HashMap<>();
63	        Map<String, RuntimeFieldStats> runtimeFieldTypes = new HashMap<>();
64	        final int mappingCount = metadata.projects().values().stream().mapToInt(p -> p.getMappingsByHash().size()).sum();
65	        final Map<MappingMetadata, Integer> mappingCounts = new IdentityHashMap<>(mappingCount);
66	
67	        final AtomicLong totalFieldCount = new AtomicLong();
68	        final AtomicLong totalDeduplicatedFieldCount = new AtomicLong();
69	        long totalMappingSizeBytes = 0L;
70	
71	        for (ProjectMetadata project : metadata.projects().values()) {
72	            for (IndexMetadata indexMetadata : project) {
73	                if (indexMetadata.isSystem()) {
74	                    // Don't include system indices in statistics about mappings,
75	                    // we care about the user's indices.
76	                    continue;
77	                }
78	                AnalysisStats.countMapping(mappingCounts, indexMetadata);
79	
80	                var sourceMode = IndexSettings.INDEX_MAPPER_SOURCE_MODE_SETTING.get(indexMetadata.getSettings());
81	                sourceModeUsageCount.merge(sourceMode.toString().toLowerCase(Locale.ENGLISH), 1, Integer::sum);
82	            }
83	            for (MappingMetadata mappingMetadata : project.getMappingsByHash().values()) {
84	                totalMappingSizeBytes += mappingMetadata.source().compressed().length;
85	            }
86	        }
87	
88	        for (Map.Entry<MappingMetadata, Integer> mappingAndCount : mappingCounts.entrySet()) {
89	            ensureNotCancelled.run();
90	            Set<String> indexFieldTypes = new HashSet<>();
91	            Set<String> indexRuntimeFieldTypes = new HashSet<>();
92	            final int count = mappingAndCount.getValue();
93	            final Map<String, Object> map = mappingAndCount.getKey().getSourceAsMap();
94	            MappingVisitor.visitMapping(map, (field, fieldMapping) -> {
95	                concreteFieldNames.add(field);
96	                String type = null;
97	                Object typeO = fieldMapping.get("type");
98	                if (typeO != null) {
99	                    type = typeO.toString();
100	                } else if (fieldMapping.containsKey("properties")) {
101	                    type = "object";
102	                }
103	                if (type != null) {
104	                    totalDeduplicatedFieldCount.incrementAndGet();
105	                    totalFieldCount.addAndGet(count);
106	                    FieldStats stats;
107	                    if (type.equals("dense_vector")) {
108	                        stats = fieldTypes.computeIfAbsent(type, DenseVectorFieldStats::new);
109	                        DenseVectorFieldStats vStats = (DenseVectorFieldStats) stats;
110	                        if (fieldMapping.containsKey("similarity")) {
111	                            Object similarity = fieldMapping.get("similarity");
112	                            vStats.vectorSimilarityTypeCount.compute(similarity.toString(), (t, c) -> c == null ? count : c + count);
113	                        }
114	                        String elementTypeStr = "float";
115	                        if (fieldMapping.containsKey("element_type")) {
116	                            Object elementType = fieldMapping.get("element_type");
117	                            elementTypeStr = elementType.toString();
118	                        }
119	                        vStats.vectorElementTypeCount.compute(elementTypeStr, (t, c) -> c == null ? count : c + count);
120	                        boolean indexed = fieldMapping.containsKey("index") && (boolean) fieldMapping.get("index");
121	                        if (indexed) {
122	                            Object indexOptions = fieldMapping.get("index_options");
123	                            // NOTE, while the default for `float` is now `int8_hnsw`, that is actually added to the mapping
124	                            // if the value is truly missing & we are indexed, we default to hnsw.
125	                            String indexTypeStr = "hnsw";
126	                            if (indexOptions instanceof Map<?, ?> indexOptionsMap) {
127	                                Object indexType = indexOptionsMap.get("type");
128	                                if (indexType != null) {
129	                                    indexTypeStr = indexType.toString();
130	                                }
131	                            }
132	                            vStats.vectorIndexTypeCount.compute(indexTypeStr, (t, c) -> c == null ? count : c + count);
133	                            vStats.indexedVectorCount += count;
134	                            Object obj = fieldMapping.get("dims");
135	                            if (obj != null) {
136	                                int dims = (int) obj;
137	                                if (vStats.indexedVectorDimMin == DenseVectorFieldStats.UNSET || dims < vStats.indexedVectorDimMin) {
138	                                    vStats.indexedVectorDimMin = dims;
139	                                }
140	                                if (vStats.indexedVectorDimMin == DenseVectorFieldStats.UNSET || dims > vStats.indexedVectorDimMax) {
141	                                    vStats.indexedVectorDimMax = dims;
142	                                }
143	                            }
144	                        } else {
145	                            vStats.vectorIndexTypeCount.compute(DenseVectorFieldStats.NOT_INDEXED, (t, c) -> c == null ? 1 : c + 1);
146	                        }
147	                    } else {
148	                        stats = fieldTypes.computeIfAbsent(type, FieldStats::new);
149	                    }
150	                    stats.count += count;
151	                    if (indexFieldTypes.add(type)) {
152	                        stats.indexCount += count;
153	                    }
154	                    Object scriptObject = fieldMapping.get("script");
155	                    if (scriptObject instanceof Map<?, ?> script) {
156	                        Object sourceObject = script.get("source");
157	                        stats.scriptCount += count;
158	                        updateScriptParams(sourceObject, stats.fieldScriptStats, count);
159	                        Object langObject = script.get("lang");
160	                        if (langObject != null) {
161	                            stats.scriptLangs.add(langObject.toString());
162	                        }
163	                    }
164	                }
165	            });
166	
167	            MappingVisitor.visitRuntimeMapping(map, (field, fieldMapping) -> {
168	                Object typeObject = fieldMapping.get("type");
169	                if (typeObject == null) {
170	                    return;
171	                }
172	                String type = typeObject.toString();
173	                RuntimeFieldStats stats = runtimeFieldTypes.computeIfAbsent(type, RuntimeFieldStats::new);
174	                stats.count += count;
175	                if (indexRuntimeFieldTypes.add(type)) {
176	                    stats.indexCount += count;
177	                }
178	                if (concreteFieldNames.contains(field)) {
179	                    stats.shadowedCount += count;
180	                }
181	                Object scriptObject = fieldMapping.get("script");
182	                if (scriptObject == null) {
183	                    stats.scriptLessCount += count;
184	                } else if (scriptObject instanceof Map<?, ?> script) {
185	                    Object sourceObject = script.get("source");
186	                    updateScriptParams(sourceObject, stats.fieldScriptStats, count);
187	                    Object langObject = script.get("lang");
188	                    if (langObject != null) {
189	                        stats.scriptLangs.add(langObject.toString());
190	                    }
191	                }
192	            });
193	        }
194	
195	        return new MappingStats(
196	            totalFieldCount.get(),
197	            totalDeduplicatedFieldCount.get(),
198	            totalMappingSizeBytes,
199	            fieldTypes.values(),
200	            runtimeFieldTypes.values(),
201	            sourceModeUsageCount
202	        );
203	    }
204	
205	    private static void updateScriptParams(Object scriptSourceObject, FieldScriptStats scriptStats, int multiplier) {
206	        if (scriptSourceObject != null) {
207	            String scriptSource = scriptSourceObject.toString();
208	            int chars = scriptSource.length();
209	            long lines = scriptSource.lines().count();
210	            int docUsages = countOccurrences(scriptSource, DOC_PATTERN);
211	            int sourceUsages = countOccurrences(scriptSource, SOURCE_PATTERN);
212	            scriptStats.update(chars, lines, sourceUsages, docUsages, multiplier);
213	        }
214	    }
215	
216	    private static int countOccurrences(String script, Pattern pattern) {
217	        int occurrences = 0;
218	        Matcher matcher = pattern.matcher(script);
219	        while (matcher.find()) {
220	            occurrences++;
221	        }
222	        return occurrences;
223	    }
224	
225	    @Nullable // for BwC
226	    private final Long totalFieldCount;
227	
228	    @Nullable // for BwC
229	    private final Long totalDeduplicatedFieldCount;
230	
231	    @Nullable // for BwC
232	    private final Long totalMappingSizeBytes;
233	
234	    private final List<FieldStats> fieldTypeStats;
235	    private final List<RuntimeFieldStats> runtimeFieldStats;
236	    private final Map<String, Integer> sourceModeUsageCount;
237	
238	    MappingStats(
239	        long totalFieldCount,
240	        long totalDeduplicatedFieldCount,
241	        long totalMappingSizeBytes,
242	        Collection<FieldStats> fieldTypeStats,
243	        Collection<RuntimeFieldStats> runtimeFieldStats,
244	        Map<String, Integer> sourceModeUsageCount
245	    ) {
246	        this.totalFieldCount = totalFieldCount;
247	        this.totalDeduplicatedFieldCount = totalDeduplicatedFieldCount;
248	        this.totalMappingSizeBytes = totalMappingSizeBytes;
249	        this.sourceModeUsageCount = sourceModeUsageCount;
250	        List<FieldStats> stats = new ArrayList<>(fieldTypeStats);
251	        stats.sort(Comparator.comparing(IndexFeatureStats::getName));
252	        this.fieldTypeStats = Collections.unmodifiableList(stats);
253	        List<RuntimeFieldStats> runtimeStats = new ArrayList<>(runtimeFieldStats);
254	        runtimeStats.sort(Comparator.comparing(RuntimeFieldStats::type));
255	        this.runtimeFieldStats = Collections.unmodifiableList(runtimeStats);
256	    }
257	
258	    MappingStats(StreamInput in) throws IOException {
259	        totalFieldCount = in.readOptionalVLong();
260	        totalDeduplicatedFieldCount = in.readOptionalVLong();
261	        totalMappingSizeBytes = in.readOptionalVLong();
262	        fieldTypeStats = in.readCollectionAsImmutableList(FieldStats::new);
263	        runtimeFieldStats = in.readCollectionAsImmutableList(RuntimeFieldStats::new);
264	        var transportVersion = in.getTransportVersion();
265	        sourceModeUsageCount = in.readImmutableMap(StreamInput::readString, StreamInput::readVInt);
266	    }
267	
268	    @Override
269	    public void writeTo(StreamOutput out) throws IOException {
270	        out.writeOptionalVLong(totalFieldCount);
271	        out.writeOptionalVLong(totalDeduplicatedFieldCount);
272	        out.writeOptionalVLong(totalMappingSizeBytes);
273	        out.writeCollection(fieldTypeStats);
274	        out.writeCollection(runtimeFieldStats);
275	        out.writeMap(sourceModeUsageCount, StreamOutput::writeVInt);
276	    }
277	
278	    private static OptionalLong ofNullable(Long l) {
279	        return l == null ? OptionalLong.empty() : OptionalLong.of(l);
280	    }
281	
282	    /**
283	     * @return the total number of fields (in non-system indices), or {@link OptionalLong#empty()} if omitted (due to BwC)
284	     */
285	    public OptionalLong getTotalFieldCount() {
286	        return ofNullable(totalFieldCount);
287	    }
288	
289	    /**
290	     * @return the total number of fields (in non-system indices) accounting for deduplication, or {@link OptionalLong#empty()} if omitted
291	     * (due to BwC)
292	     */
293	    public OptionalLong getTotalDeduplicatedFieldCount() {
294	        return ofNullable(totalDeduplicatedFieldCount);
295	    }
296	
297	    /**
298	     * @return the total size of all mappings (including those for system indices) accounting for deduplication and compression, or {@link
299	     * OptionalLong#empty()} if omitted (due to BwC).
300	     */
301	    public OptionalLong getTotalMappingSizeBytes() {
302	        return ofNullable(totalMappingSizeBytes);
303	    }
304	
305	    /**
306	     * Return stats about field types.
307	     */
308	    public List<FieldStats> getFieldTypeStats() {
309	        return fieldTypeStats;
310	    }
311	
312	    /**
313	     * Return stats about runtime field types.
314	     */
315	    public List<RuntimeFieldStats> getRuntimeFieldStats() {
316	        return runtimeFieldStats;
317	    }
318	
319	    public Map<String, Integer> getSourceModeUsageCount() {
320	        return sourceModeUsageCount;
321	    }
322	
323	    @Override
324	    public XContentBuilder toXContent(XContentBuilder builder, Params params) throws IOException {
325	        builder.startObject("mappings");
326	        if (totalFieldCount != null) {
327	            builder.field("total_field_count", totalFieldCount);
328	        }
329	        if (totalDeduplicatedFieldCount != null) {
330	            builder.field("total_deduplicated_field_count", totalDeduplicatedFieldCount);
331	        }
332	        if (totalMappingSizeBytes != null) {
333	            builder.humanReadableField(
334	                "total_deduplicated_mapping_size_in_bytes",
335	                "total_deduplicated_mapping_size",
336	                ByteSizeValue.ofBytes(totalMappingSizeBytes)
337	            );
338	        }
339	        builder.startArray("field_types");
340	        for (IndexFeatureStats st : fieldTypeStats) {
341	            st.toXContent(builder, params);
342	        }
343	        builder.endArray();
344	        builder.startArray("runtime_field_types");
345	        for (RuntimeFieldStats st : runtimeFieldStats) {
346	            st.toXContent(builder, params);
347	        }
348	        builder.endArray();
349	        builder.startObject("source_modes");
350	        var entries = sourceModeUsageCount.entrySet().stream().sorted(Map.Entry.comparingByKey()).toList();
351	        for (var entry : entries) {
352	            builder.field(entry.getKey(), entry.getValue());
353	        }
354	        builder.endObject();
355	        builder.endObject();
356	        return builder;
357	    }
358	
359	    @Override
360	    public String toString() {
361	        return Strings.toString(this, true, true);
362	    }
363	
364	    @Override
365	    public boolean equals(Object o) {
366	        if (this == o) return true;
367	        if (o == null || getClass() != o.getClass()) return false;
368	        MappingStats that = (MappingStats) o;
369	        return Objects.equals(totalFieldCount, that.totalFieldCount)
370	            && Objects.equals(totalDeduplicatedFieldCount, that.totalDeduplicatedFieldCount)
371	            && Objects.equals(totalMappingSizeBytes, that.totalMappingSizeBytes)
372	            && fieldTypeStats.equals(that.fieldTypeStats)
373	            && runtimeFieldStats.equals(that.runtimeFieldStats)
374	            && sourceModeUsageCount.equals(that.sourceModeUsageCount);
375	    }
376	
377	    @Override
378	    public int hashCode() {
379	        return Objects.hash(
380	            totalFieldCount,
381	            totalDeduplicatedFieldCount,
382	            totalMappingSizeBytes,
383	            fieldTypeStats,
384	            runtimeFieldStats,
385	            sourceModeUsageCount
386	        );
387	    }
388	}
